import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import {memo, useMemo} from 'react'

import {useBooleanQueryParam} from '../../../../../hooks/routes'
import RunButton from '../../../../common/RunPipelineButton/RunPipelineButton'
import CancelChangesButton from '../../components/ChangesButton/Cancel/CancelChangesButton'
import {useSaveChangesState} from '../../components/ChangesButton/hooks/useSaveChangesState'
import SaveChangesButton from '../../components/ChangesButton/Save/SaveChangesButton'
import type {pipelineHeadBuildTypeFragment$key} from '../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineHead, usePipelineId} from '../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../hooks/usePermissionCanEditPipeline'
import {
  useEditPipeline,
  useIsDebugRunning,
  useSaveYAMLChangesHandler,
} from '../EditPipelinePage.hooks'

import useSaveChangesError from './hooks/useSaveChangesError'

import styles from './SaveChanges.module.css'

type Props = {
  className?: string
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
  hasVcsRoot?: boolean
}

function SaveChanges({className, pipelineHeadBuildTypeKey, hasVcsRoot}: Props) {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const pipelineId = usePipelineId()
  const isYaml = useBooleanQueryParam('yaml')

  const isReadonly = useIsDebugRunning()
  const head = usePipelineHead(pipelineHeadBuildTypeKey)

  const saveChangesError = useSaveChangesError(pipelineId)
  const editPipeline = useEditPipeline()
  const [saveYAMLChangesHandler] = useSaveYAMLChangesHandler()

  const {hasErrors, hasChanges} = useSaveChangesState()

  const saveAndRunTooltip =
    hasChanges && !canEditPipeline
      ? "You can't run the pipeline with the new changes. Copy the YAML to avoid losing them, then contact a project admin for access."
      : isYaml
        ? ''
        : saveChangesError.errorJobsLabel
  const handlerSaveButtonClick = isYaml
    ? saveYAMLChangesHandler
    : editPipeline.handlerSaveButtonClick

  const popupProps = useMemo(
    () => ({
      offset: 10,
      autoCorrectTopOverflow: true,
      directions: [Directions.BOTTOM_CENTER],
    }),
    [],
  )

  if (isReadonly) {
    return <RunButton primary disabled={!hasVcsRoot} hasVcsRoot={hasVcsRoot} />
  }

  return (
    <div className={classNames(styles.container, className)}>
      <div className={styles.actions}>
        {hasChanges && (
          <>
            <CancelChangesButton className={styles.button} />
            <SaveChangesButton className={styles.button} />
          </>
        )}
        <Tooltip popupProps={popupProps} title={saveAndRunTooltip}>
          <RunButton
            className={styles.button}
            headId={head?.id}
            projectId={head?.projectId}
            beforeRun={handlerSaveButtonClick}
            disabled={(hasChanges && !canEditPipeline) || hasErrors || !hasVcsRoot}
            hasVcsRoot={hasVcsRoot}
            primary
          >
            {hasChanges ? 'Save and run' : 'Run'}
          </RunButton>
        </Tooltip>
      </div>
    </div>
  )
}

export default memo(SaveChanges)
