import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {memo} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {useAppDispatch} from '../../../../../../hooks/react-redux'
import {getHrefWithQueryParams} from '../../../../../../routes'
import {
  pipelineDraft,
  pipelineErrors,
  pipelineSecrets,
  pipelineYaml,
} from '../../../EditPipelinePage/slices/EditPipelinePage.slices'
import {usePipelineId} from '../../../hooks/pipeline'
import {useSaveChangesState} from '../hooks/useSaveChangesState'

interface Props {
  className?: string
}
function CancelChangesButton(props: Props) {
  const {className} = props
  const navigate = useNavigate()
  const location = useLocation()
  const dispatch = useAppDispatch()
  const pipelineId = usePipelineId()

  const {isLoading} = useSaveChangesState()
  const cancel = () => {
    dispatch(pipelineDraft.actions.reset(pipelineId))
    dispatch(pipelineYaml.actions.reset(pipelineId))
    dispatch(pipelineErrors.actions.clear({pipelineId}))
    dispatch(pipelineSecrets.actions.unsetAll(pipelineId))
    navigate(getHrefWithQueryParams(location, null, {edit: 'true', yaml: 'false'}), {
      replace: true,
      preventScrollReset: true,
    })
  }

  return (
    <Button height={ControlsHeight.M} onClick={cancel} className={className} disabled={isLoading}>
      {'Cancel'}
    </Button>
  )
}

export default memo(CancelChangesButton)
