import type {MouseEvent} from 'react'
import {memo, useCallback} from 'react'

import {useBooleanQueryParam} from '../../../../../hooks/routes'
import {getPipelineHref} from '../../../../../routes'
import type {RouterButtonProps} from '../../../../common/RouterLink/RouterLink'
import ToggleLink from '../../../../common/ToggleLink/ToggleLink'
import Tooltip from '../../../../common/Tooltip/Tooltip'
import {usePipelineId} from '../../hooks/pipeline'
import {
  isPipelinesEnabledInExclusiveMode,
  isWithoutVcsFeatureEnabled,
} from '../../utils/featureToggles'

import usePipelineEditButton from './usePipelineEditButton'

import styles from './PipelineEditButton.module.css'

type PipelineEditButtonProps = {
  hasVcsRoot?: boolean
  showRepositoryRequiredDialog?: (to?: string) => void
} & RouterButtonProps

function PipelineEditButton({
  hasVcsRoot,
  showRepositoryRequiredDialog,
  ...restProps
}: PipelineEditButtonProps) {
  const pipelineId = usePipelineId()
  const isEdit = useBooleanQueryParam('edit')
  const label = 'Settings'
  const {popupProps, canEditPipeline, canViewPipelineSettings, permissionDenyMessage} =
    usePipelineEditButton(hasVcsRoot)

  const onClick = useCallback(
    (event: MouseEvent) => {
      if (!hasVcsRoot && isWithoutVcsFeatureEnabled) {
        event.preventDefault()
        showRepositoryRequiredDialog?.(`${getPipelineHref(pipelineId)}?edit=true`)
      }
    },
    [hasVcsRoot, pipelineId, showRepositoryRequiredDialog],
  )

  if (!isPipelinesEnabledInExclusiveMode() && !canViewPipelineSettings) {
    return null
  }

  return (
    <>
      <Tooltip
        delay={100}
        className={styles.tooltipWrapper}
        popupProps={popupProps}
        title={
          permissionDenyMessage ??
          (isEdit
            ? 'Exit Settings Mode'
            : canEditPipeline
              ? 'Edit settings'
              : 'View settings (no edit permissions)')
        }
      >
        <ToggleLink
          {...restProps}
          icon={'settings-modifier'}
          label={label}
          checked={isEdit}
          disabled={!canViewPipelineSettings}
          onClick={onClick}
        />
      </Tooltip>
    </>
  )
}

export default memo(PipelineEditButton)
