import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {memo, Suspense} from 'react'

import {useBooleanQueryParam} from '../../../../../hooks/routes'
import PageTitle from '../../../../common/PageTitle/PageTitle'
import ProjectOrBuildTypeIcon from '../../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon'
import {EntityIconType} from '../../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import {usePipelineNameOrDraft} from '../../EditPipelinePage/EditPipelinePage.hooks'
import SaveChanges from '../../EditPipelinePage/SaveChanges/SaveChanges'
import type {pipelineHeadBuildTypeFragment$key} from '../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import PipelineEditButton from '../PipelineEditButton/PipelineEditButton'

import styles from './Header.module.css'

function EditPipelinePageTitle() {
  const name = usePipelineNameOrDraft()

  return (
    <div className={styles.heading}>
      {name && (
        <PageTitle className={styles.title} title={name}>
          <ProjectOrBuildTypeIcon type={EntityIconType.PIPELINE} size="L" edit={'true'} />
          {name}
        </PageTitle>
      )}
    </div>
  )
}

type Props = {
  pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null
  className?: string | null
  icon?: ReactNode
  title?: string
  preservedQueryParams?: string
  contentClassName?: string
  hasVcsRoot?: boolean
  showRepositoryRequiredDialog?: (to?: string) => void
  content: ReactNode
  actions: ReactNode
  showBottomBorder: boolean
}
function Header({
  pipelineHeadBuildTypeKey,
  className,
  icon,
  title,
  preservedQueryParams = '',
  contentClassName,
  hasVcsRoot,
  showRepositoryRequiredDialog,
  content,
  actions,
  showBottomBorder,
}: Props) {
  const isEdit = useBooleanQueryParam('edit')

  return (
    <div
      className={classNames(styles.header, className, {
        [styles.headerBottomLine]: isEdit || showBottomBorder,
      })}
    >
      {isEdit ? (
        <EditPipelinePageTitle />
      ) : (
        <>
          <div className={styles.heading}>
            <PageTitle className={styles.title}>
              {icon}
              {title}
            </PageTitle>
          </div>
          <div className={classNames(styles.content, contentClassName)}>{content}</div>
        </>
      )}
      <div className={styles.actions}>
        <Suspense>
          {isEdit ? (
            <SaveChanges
              hasVcsRoot={hasVcsRoot}
              pipelineHeadBuildTypeKey={pipelineHeadBuildTypeKey}
            />
          ) : (
            actions
          )}
          <PipelineEditButton
            hasVcsRoot={hasVcsRoot}
            showRepositoryRequiredDialog={showRepositoryRequiredDialog}
            to={{
              search: isEdit
                ? ''
                : objectToQuery({edit: 'true'}).concat(
                    preservedQueryParams ? `&${preservedQueryParams}` : '',
                  ),
            }}
          />
        </Suspense>
      </div>
    </div>
  )
}
export default memo(Header)
