import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {useMemo} from 'react'

import usePermissionCanEditPipeline from '../../hooks/usePermissionCanEditPipeline'
import {addRepositoryNoPermissionsMessage} from '../RepositoryRequiredDialog/RepositoryRequiredDialog.consts'

import {viewSettingsPermissionDenyMessage} from './PipelineEditButton.consts'

import styles from './PipelineEditButton.module.css'

function usePipelineEditButton(hasVcsRoot?: boolean) {
  const {canEditPipeline, canViewPipelineSettings} = usePermissionCanEditPipeline()

  let permissionDenyMessage
  if (!canViewPipelineSettings) {
    permissionDenyMessage = viewSettingsPermissionDenyMessage
    if (!hasVcsRoot) {
      permissionDenyMessage = addRepositoryNoPermissionsMessage
    }
  }

  const popupProps = useMemo(
    () => ({
      offset: 8,
      directions: [Directions.BOTTOM_LEFT, Directions.BOTTOM_RIGHT],
      className: styles.popup,
    }),
    [],
  )

  return {
    popupProps,
    canEditPipeline,
    canViewPipelineSettings,
    permissionDenyMessage,
  }
}

export default usePipelineEditButton
