import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {memo} from 'react'

import {useBooleanQueryParam} from '../../../../../../hooks/routes'
import {
  useEditPipeline,
  useSaveYAMLChangesHandler,
} from '../../../EditPipelinePage/EditPipelinePage.hooks'
import useSaveChangesError from '../../../EditPipelinePage/SaveChanges/hooks/useSaveChangesError'
import {usePipelineId} from '../../../hooks/pipeline'
import usePermissionCanEditPipeline from '../../../hooks/usePermissionCanEditPipeline'
import {useSaveChangesState} from '../hooks/useSaveChangesState'

const popupProps = {
  offset: 10,
  autoCorrectTopOverflow: true,
  directions: [Directions.BOTTOM_CENTER],
}

interface Props {
  className?: string
}
function SaveChangesButton(props: Props) {
  const {canEditPipeline} = usePermissionCanEditPipeline()
  const {className} = props
  const pipelineId = usePipelineId()
  const isYaml = useBooleanQueryParam('yaml')

  const saveChangesError = useSaveChangesError(pipelineId)
  const editPipeline = useEditPipeline()
  const [saveYAMLChangesHandler] = useSaveYAMLChangesHandler()

  const {hasErrors, isLoading} = useSaveChangesState()

  const tooltip = !canEditPipeline
    ? "You can't save the changes in the pipeline. Copy the YAML to avoid losing them, then contact a project admin for access."
    : isYaml
      ? ''
      : saveChangesError.errorJobsLabel
  const handlerSaveButtonClick = isYaml
    ? saveYAMLChangesHandler
    : editPipeline.handlerSaveButtonClick

  return (
    <Tooltip popupProps={popupProps} title={tooltip}>
      <Button
        primary
        height={ControlsHeight.M}
        className={className}
        disabled={!canEditPipeline || hasErrors}
        onClick={handlerSaveButtonClick}
        loader={isLoading}
      >
        {'Save'}
      </Button>
    </Tooltip>
  )
}

export default memo(SaveChangesButton)
